import{_ as s,l as c,o as e,c as i,v as t,p as l,x as r,d as n,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"预取","description":"","frontmatter":{"title":"预取","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cache-prefetch.md","filePath":"cs/cache-prefetch.md","lastUpdated":1789023840000}'),d={name:"cs/cache-prefetch.md"};function A(E,a,B,f,m,_){const o=c("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="预取" tabindex="-1">预取 <a class="header-anchor" href="#预取" aria-label="Permalink to &quot;预取&quot;">​</a></h1><div class="epigraph"><p>强制缺失逃不掉「第一次见这块」，但可以把第一次安排在 CPU 真正 load 之前；猜错则占带宽和 MSHR。</p><footer>—— 据 Jouppi, Improving Direct-Mapped Cache Performance by the Addition of a Small Fully-Associative Cache and Prefetch Buffers, ISCA 1990；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/mshr">上一课</a>让未完成的块请求有地方挂。缺失分类里，预取被点名为对付强制缺失的手段。本课不重画 MSHR。缺口是：硬件或软件如何<strong>在需求 load 之前发出块请求</strong>，以及预取与容量/污染的交易。本课只钉流预取与预取缓冲的直觉，不把编译器软件预取指令写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>冷缺失在无限 cache 上仍在。若轨迹是数组顺序扫，下一块地址可预测。<a href="/cs/locality-principle">局部性原理</a>的空间局部性已经说「附近会用」；cache 行只覆盖当前块，下一块仍可能冷。缺口不是提高相联度，而是<strong>按步长发出未来块的读，填入 cache 或一小块预取缓冲</strong>。</p><p>猜错：把不会用的块请来，挤掉有用行（污染），并占用上一课的 MSHR 与 DRAM 带宽。预取及时性：太早被踢，太晚等于普通缺失。</p><p><span class="marginnote">Jouppi 1990 的 stream buffer 把预取与 L1 分开，减少直接映射的冲突污染。教学上可把它看成「预取不要直接写进唯一那一路」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>硬件流预取：连续缺失若地址相差固定块距，为该流分配一个流缓冲，按该步长向前发。命中缓冲则提升为 cache 填入或直接转发。软件：在循环里插入预取提示，地址由编译器算；提示失败不得产生异常。</p>',9)),(e(),l(h,null,{default:r(()=>[p(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20STR%5B%22%E6%A3%80%E5%87%BA%E5%9B%BA%E5%AE%9A%E6%AD%A5%E9%95%BF%22%5D%20--%3E%20PF%5B%22%E5%90%91%20MSHR%20%E5%8F%91%E6%9C%AA%E6%9D%A5%E5%9D%97%22%5D%0A%20%20PF%20--%3E%20BUF%5B%22%E9%A2%84%E5%8F%96%E7%BC%93%E5%86%B2%E6%88%96%20cache%22%5D%0A%20%20BUF%20--%3E%7C%22CPU%20load%20%E5%91%BD%E4%B8%AD%22%7C%20WIN%5B%22%E5%BC%BA%E5%88%B6%E7%BC%BA%E5%A4%B1%E8%A2%AB%E6%8E%A9%E7%9B%96%22%5D%0A%20%20BUF%20--%3E%7C%22%E4%BB%8E%E6%9C%AA%E7%94%A8%22%7C%20POLL%5B%22%E6%B1%A1%E6%9F%93%E4%B8%8E%E5%B8%A6%E5%AE%BD%E6%B5%AA%E8%B4%B9%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>预取缺失通常不阻塞流水线：它本来就是提前的 MSHR 事务。需求缺失仍按上一课唤醒。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>预取改的是强制项的<strong>有效延迟</strong>，不是数学上消灭第一次引用。容量缺失靠预取很难：工作集已经装不下，再请来只是换哪些块在 SRAM 里。冲突可以用预取缓冲绕开直接映射的互踢，这与加路是另一笔交易。</p><p><a href="/cs/cpi-amdahl">CPI 与阿姆达尔</a>：预取把一部分缺失延迟与计算重叠。重叠不满时，\\(f\\) 仍在。过度预取让 DRAM 调度更乱，后课时序课会碰到。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入指针追逐的依赖预取（那几乎就是提前 load），不把 GPU 的软件预取当主干。多层 cache 之间谁包含谁，会影响「预取填在哪一层」——下一课包含/互斥。也不把预取写成 MESI 事务的替代。</p><p>后课默认：顺序与固定步长轨迹允许硬件预取；预取走 MSHR。层次之间的包含关系是下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>预取把强制缺失提前到需求之前，靠空间局部性与步长。</li><li>错预取污染 cache 并占用 MSHR 与带宽。</li><li>多层谁必须包含谁，是下一课的缺口。</li><li>出处：Jouppi, <em>ISCA</em>, 1990；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',9))])}const P=s(d,[["render",A]]);export{C as __pageData,P as default};
